// Offline raw corpus -> production RTMPose/triangulation, without postprocessing.
// Plans must be generated by run_corpus.py after checksum/timestamp validation.
#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
#include <yaml-cpp/yaml.h>
#include <opencv2/imgcodecs.hpp>
#include "infer/rtmpose.hpp"
#include "infer/yolox.hpp"
#include "lift/keypoint_format.hpp"
#include "lift/triangulator.hpp"

using namespace fitra;
namespace {
void require(bool ok, const std::string& message) {
    if (!ok) throw std::runtime_error(message);
}
struct Logger : nvinfer1::ILogger {
    void log(Severity severity, const char* message) noexcept override {
        if (severity <= Severity::kWARNING) std::cerr << "[TRT] " << message << '\n';
    }
};
std::uint64_t fingerprint(std::istream& in) {
    std::uint64_t value = 14695981039346656037ULL;
    for (char c; in.get(c);) { value ^= static_cast<unsigned char>(c); value *= 1099511628211ULL; }
    require(in.eof(), "plan read failed");
    in.clear(); in.seekg(0);
    return value;
}
cv::Mat decode(const YAML::Node& frame, const YAML::Node& camera) {
    const auto path = frame["payload_path"].as<std::string>();
    const auto offset = frame["offset"].as<std::uint64_t>();
    const auto size = frame["size"].as<std::uint64_t>();
    require(camera["raw_encoding"].as<std::string>() == "jpeg", "only raw JPEG corpus is supported");
    const auto length = std::filesystem::file_size(path);
    require(size > 0 && size <= 64*1024*1024 && offset <= length && size <= length-offset,
            "payload range outside file or frame size limit");
    std::ifstream in(path, std::ios::binary);
    in.seekg(static_cast<std::streamoff>(offset));
    std::vector<unsigned char> bytes(size);
    in.read(reinterpret_cast<char*>(bytes.data()), static_cast<std::streamsize>(size));
    require(in.good(), "payload read failed");
    auto image = cv::imdecode(bytes, cv::IMREAD_COLOR);
    require(!image.empty(), "JPEG decode failed");
    require(image.cols == camera["capture_width"].as<int>() && image.rows == camera["capture_height"].as<int>(),
            "decoded resolution differs from capture manifest");
    return image;
}
}

int main(int argc, char** argv) {
    try {
        if (argc == 2 && std::string(argv[1]) == "--help") {
            std::cout << "corpus_infer PLAN CALIB DET_ENGINE POSE_ENGINE NEW_OUTPUT\n"
                         "CPU JPEG decode, shared TRT contexts, raw 3D; no IK/Kalman/floor.\n";
            return 0;
        }
        require(argc == 6, "usage: corpus_infer PLAN CALIB DET_ENGINE POSE_ENGINE NEW_OUTPUT");
        require(!std::filesystem::exists(argv[5]), "output exists; choose a new path");
        std::ifstream plan(argv[1]);
        require(plan.good(), "cannot open plan");
        const auto binding = fingerprint(plan);
        std::string line;
        require(static_cast<bool>(std::getline(plan, line)), "missing plan header");
        const auto header = YAML::Load(line);
        require(header["schema"].as<std::string>() == "fitra_corpus_inference_plan_v1", "unsupported plan");
        const auto semantics = header["time_basis"].as<std::string>();
        require(semantics == "monotonic_soe" || semantics == "monotonic_eof", "measured kernel clock required");
        const auto cameras = header["cameras"];
        require(cameras.IsSequence() && cameras.size() == 3, "three cameras required");
        std::vector<std::string> ids;
        for (std::size_t c=0; c<cameras.size(); ++c) {
            require(cameras[c]["index"].as<std::size_t>() == c, "camera order mismatch");
            ids.push_back("cam" + std::to_string(cameras[c]["config_slot"].as<unsigned>()));
        }
        auto unique_ids=ids;
        std::sort(unique_ids.begin(),unique_ids.end());
        require(std::adjacent_find(unique_ids.begin(),unique_ids.end())==unique_ids.end(), "duplicate camera ID");
        lift::set_active_keypoint_format(lift::KeypointFormat::Halpe26);
        auto calib = lift::select_calib_cameras(lift::load_calibration(argv[2]), ids);
        lift::Triangulator triangulator(calib);
        triangulator.require_camera_ids(ids);
        for (std::size_t c=0; c<3; ++c) {
            require(calib.cameras[c].intrinsics.width == cameras[c]["capture_width"].as<int>() &&
                    calib.cameras[c].intrinsics.height == cameras[c]["capture_height"].as<int>(),
                    "calibration resolution mismatch; no implicit scaling or crop");
        }
        Logger logger;
        std::unique_ptr<nvinfer1::IRuntime> runtime(nvinfer1::createInferRuntime(logger));
        require(runtime != nullptr, "TensorRT runtime unavailable");
        auto det_engine = infer::TrtEngine::from_file(*runtime, argv[3], logger);
        auto pose_engine = infer::TrtEngine::from_file(*runtime, argv[4], logger);
        infer::Yolox::Options det_opts;
        det_opts.score_thr = 0.7f;
        infer::Yolox detector(*det_engine, det_opts);
        infer::RtmPose pose(*pose_engine);
        std::ofstream out(argv[5]);
        require(out.good(), "cannot open output");
        out << std::setprecision(9)
            << "{\"schema\":\"fitra_corpus_raw3d_v1\",\"plan_fnv1a64\":\"" << binding
            << "\",\"kp_format\":\"halpe26\",\"postprocessing\":false,\"det_score\":0.7,"
               "\"kp_conf_thresh\":0.3,\"max_reproj_px\":6,\"identity_policy\":\"reject_ambiguous_detections\"}\n";
        std::int64_t previous_time=-1, previous_seq=-1;
        std::size_t processed=0;
        while (std::getline(plan,line)) {
            const auto row = YAML::Load(line);
            const auto time = row["capture_max_ns"].as<std::int64_t>();
            const auto seq = row["seq"].as<std::int64_t>();
            require(time > previous_time && seq > previous_seq, "nonmonotonic group sequence/time");
            const auto frames = row["frames"];
            require(frames.IsSequence() && frames.size()==3, "incomplete group");
            std::vector<cv::Mat> images(3);
            std::vector<infer::RtmPose::Request> requests;
            std::vector<int> request_cameras;
            std::vector<std::size_t> detections(3);
            std::int64_t oldest=time, newest=0;
            bool ambiguous=false;
            for (std::size_t c=0; c<3; ++c) {
                require(frames[c]["camera"].as<std::size_t>()==c, "frame camera mismatch");
                require(frames[c]["v4l2_semantics"].as<std::string>()==semantics, "timestamp semantics mismatch");
                const auto t=frames[c]["v4l2_mono_ns"].as<std::int64_t>();
                oldest=std::min(oldest,t); newest=std::max(newest,t);
                images[c]=decode(frames[c],cameras[c]);
                const auto boxes=detector.infer(images[c]);
                detections[c]=boxes.size();
                ambiguous |= boxes.size()>1;
                if (boxes.size()==1) { requests.push_back({&images[c],boxes[0]}); request_cameras.push_back(c); }
            }
            require(newest==time && newest-oldest<=header["window_ns"].as<std::int64_t>(), "group time/skew mismatch");
            lift::TriangulatedSkeleton tri;
            std::vector<infer::Person> persons;
            if (!ambiguous) {
                persons=pose.infer_batch(requests);
                require(persons.size()==requests.size(), "pose batch cardinality mismatch");
                std::vector<lift::PerCameraObservation> observations;
                for (std::size_t i=0; i<persons.size(); ++i) observations.push_back({request_cameras[i],&persons[i]});
                tri=triangulator.triangulate(observations);
            }
            out << "{\"seq\":" << seq << ",\"t_ns\":" << time
                << ",\"ambiguous_detection\":" << (ambiguous?"true":"false") << ",\"detections\":[";
            for (std::size_t c=0;c<3;++c) { if(c) out<<','; out<<detections[c]; }
            out << "],\"valid_joints\":" << tri.valid_joints << ",\"median_reproj_px\":";
            if(tri.valid_joints) out<<tri.median_reproj_px; else out<<"null";
            out << ",\"joints\":[";
            for(std::size_t k=0;k<26;++k) {
                if(k) out<<',';
                const auto& j=tri.skeleton.joints[k];
                if(!j.valid) { out<<"null"; continue; }
                require(std::isfinite(j.x)&&std::isfinite(j.y)&&std::isfinite(j.z)&&std::isfinite(j.score)&&j.score>=0,
                        "nonfinite triangulated joint");
                out<<'['<<j.x<<','<<j.y<<','<<j.z<<','<<j.score<<']';
            }
            out << "],\"joint_quality\":[";
            for(std::size_t k=0;k<26;++k) {
                if(k) out<<',';
                // Nose direction endpoint (Halpe slot 0) is synthetic, not a measured quality sample.
                if(!tri.skeleton.joints[k].valid || k==0) { out<<"null"; continue; }
                out<<"{\"views\":"<<tri.view_count[k]<<",\"reproj_px\":"<<tri.reproj_error_px[k]
                   <<",\"ray_angle_deg\":"<<tri.max_ray_angle_deg[k]<<'}';
            }
            out << "],\"observations_2d\":[";
            for (std::size_t c=0;c<3;++c) {
                if(c) out<<',';
                const auto it=std::find(request_cameras.begin(),request_cameras.end(),c);
                if(ambiguous || it==request_cameras.end()) { out<<"null"; continue; }
                const auto& person=persons[std::distance(request_cameras.begin(),it)];
                out<<'[';
                for(std::size_t k=0;k<26;++k) {
                    if(k) out<<',';
                    const auto& p=person.kpts[k];
                    require(std::isfinite(p.x)&&std::isfinite(p.y)&&std::isfinite(p.score),"nonfinite 2D pose");
                    out<<'['<<p.x<<','<<p.y<<','<<p.score<<']';
                }
                out<<']';
            }
            out << "]}\n";
            require(out.good(), "output write failed");
            previous_time=time; previous_seq=seq;
            if(++processed%100==0) std::cerr<<"processed "<<processed<<" groups\n";
        }
        require(plan.eof()&&processed>0,"incomplete or empty plan");
        out.close(); require(out.good(),"output close failed");
        std::cerr<<"done "<<processed<<" groups (raw 3D, no live schedule claim)\n";
        return 0;
    } catch(const std::exception& e) { std::cerr<<"corpus_infer: "<<e.what()<<'\n'; return 1; }
}
